<script>
 import {onMount,tick} from 'svelte';
 import WindowControls from './WindowControls.svelte';
 import {colorMeterWindow,colorMeterCapabilities} from './color-meter-state.js';
 import {COLOR_METER_APERTURES,meterReadout} from './color-meter-pixels.js';
 import {colorMeterMenus} from './color-meter-menus.js';
 import {createColorMeterNativeView,colorMeterKeyboard} from './color-meter-native-view.js';
 import './color-meter.css';
 let {state: colorMeterState,profile,windowId,window:actualWindow=null,execute,registerView,available=true,active=true,controls={}}=$props();
 let root=$state(null),message=$state('');let originalState,originalProfile,originalId,facade,retired=false,pendingPoint=null,pointerTimer=null,busy=false;
 const id=$derived(windowId??actualWindow?.id),session=$derived(colorMeterWindow(colorMeterState,id)),cap=$derived(colorMeterCapabilities(profile)),groups=$derived(colorMeterMenus({state: colorMeterState,profile,windowId:id})),menu=$derived(groups.find(g=>g.id===session?.menu)),readout=$derived(session?.sample?meterReadout(session.sample.rgb,session.space,session.format):null);
 const spaces=[['native','Display native values'],['srgb','Display in sRGB'],['display-p3','Display in Display P3'],['adobe-rgb','Display in Adobe RGB (1998)'],['generic-rgb','Display in Generic RGB · local'],['lab','Display in L*a*b*']];
 const swatch=$derived(session?.sample?`rgb(${session.sample.rgb.map(Math.round).join(',')})`:'transparent');
 function current(){return !retired&&root?.isConnected&&colorMeterState===originalState&&profile===originalProfile&&id===originalId;}
 async function command(suffix,payload={}){if(!current()||!available||!active)return;const original=root,response=await execute(`colormeter.${suffix}`,{windowId:id},payload);if(current()&&root===original)message=response?.status==='applied'?'':response?.error?.message??'The local meter operation is unavailable.';return response;}
 async function menuAction(item){if(!current()||!item.enabled||!item.request)return;const response=await command(item.request.command.slice('colormeter.'.length),item.request.payload);if(response?.status==='applied'&&current()&&session.menu)command('sheet',{menu:null});}
 function pointer(event){if(!current()||!available||!active||session?.frozen||session?.sheet||session?.menu)return;pendingPoint={x:event.clientX,y:event.clientY};if(pointerTimer===null&&!busy)pointerTimer=setTimeout(samplePointer,140);}
 async function samplePointer(){pointerTimer=null;if(!pendingPoint||busy||!current())return;const point=pendingPoint;pendingPoint=null;busy=true;try{await command('sample',point);}finally{busy=false;if(pendingPoint&&current())pointerTimer=setTimeout(samplePointer,140);}}
 function keyboard(event){if(!current()||!available||!active)return;if(event.key==='Escape'&&(session.menu||session.sheet)){event.preventDefault();command('sheet',{menu:null,sheet:null});return;}if(event.target.matches('input,select,textarea'))return;const request=colorMeterKeyboard(event);if(request){event.preventDefault();command(request.suffix,request.payload);}}
 onMount(()=>{originalState=colorMeterState;originalProfile=profile;originalId=id;facade=createColorMeterNativeView({getRoot:()=>root,getState:()=>colorMeterState,getProfile:()=>profile,windowId:id,available:()=>current()&&available&&active,tick});registerView?.(id,facade);root.ownerDocument.addEventListener('pointermove',pointer);return()=>{retired=true;if(pointerTimer!==null)clearTimeout(pointerTimer);root?.ownerDocument.removeEventListener('pointermove',pointer);facade.destroy();registerView?.(originalId,null,facade);};});
</script>
<section bind:this={root} class="color-meter-app" class:classic={cap.classic} class:windows={cap.windows} class:golden={cap.golden} class:inactive={!active} data-color-meter-window={id} data-profile={profile.id} role="region" aria-label={cap.label} tabindex="0" onkeydown={keyboard}>
 {#if session}
 <header class="color-meter-titlebar">{#if !cap.windows}<WindowControls {active} onclose={()=>command('window.close')} onminimize={controls.onminimize} onzoom={controls.onzoom} onfullscreen={controls.onfullscreen} fullScreen={controls.fullScreen}/>{/if}<strong>{cap.label}</strong></header>
 <div class="color-meter-body" inert={!available||!active||!!session.sheet}>
 <nav class="color-meter-menu-strip" aria-label="Meter menus">{#each groups.filter(g=>g.id!=='meter') as group}<button data-color-meter-control={`menu:${group.id}`} aria-expanded={session.menu===group.id} onclick={()=>command('sheet',{menu:session.menu===group.id?null:group.id})}>{group.label}</button>{/each}</nav>
 {#if menu}<div class="color-meter-menu" role="menu" aria-label={menu.label}>{#each menu.children as item}{#if item.children}<details><summary>{item.label}</summary>{#each item.children as child}<button disabled={!child.enabled} data-color-meter-control={child.id} role="menuitemradio" aria-checked={!!child.checked} onclick={()=>menuAction(child)}>{child.checked?'✓ ':''}{child.label}</button>{/each}</details>{:else}<button disabled={!item.enabled} data-color-meter-control={item.id} role={item.checked!==undefined?'menuitemcheckbox':'menuitem'} aria-checked={item.checked} onclick={()=>menuAction(item)}><span>{item.checked?'✓ ':''}{item.label}</span><kbd>{item.shortcut??''}</kbd></button>{/if}{/each}</div>{/if}
 <div class="color-meter-instrument"><div class="color-meter-left"><canvas width="128" height="128" data-color-meter-preview aria-label="Magnified genuine simulated desktop raster"></canvas><label class="color-meter-aperture"><input type="range" min="0" max="5" step="1" value={COLOR_METER_APERTURES.indexOf(session.aperture)} data-color-meter-control="aperture" aria-label="Aperture Size" onchange={event=>command('settings',{aperture:COLOR_METER_APERTURES[Number(event.currentTarget.value)]})}/><span>Aperture Size</span></label></div>
 <div class="color-meter-right"><select value={session.space} data-color-meter-control="space" aria-label="Color space" onchange={event=>command('settings',{space:event.currentTarget.value})}>{#each spaces as [value,label]}<option {value}>{label}</option>{/each}</select><div class="color-meter-reading"><div class="color-meter-swatch" style:background={swatch} aria-label="Measured color swatch"></div><div class="color-meter-values" aria-live="polite">{#each readout?.labels??['R','G','B'] as label,index}<output>{label}: <span>{readout?.values[index]??'—'}</span></output>{/each}</div></div><span class="color-meter-display">Simulated Color LCD</span><span class="color-meter-lock">{session.frozen?'Color frozen':session.lockX&&session.lockY?'Position locked':session.lockX?'X locked':session.lockY?'Y locked':`${session.magnification}× magnification`}</span></div></div>
 <footer><button data-color-meter-control="refresh" disabled={session.frozen} onclick={()=>command('refresh')}>Sample Position</button><button data-color-meter-control="freeze" disabled={!session.sample} aria-pressed={session.frozen} onclick={()=>command('freeze')}>{session.frozen?'Resume':'Freeze'}</button><button data-color-meter-control="copy" disabled={!session.sample} onclick={()=>command('copy',{kind:'text'})}>Copy</button><button data-color-meter-control="help" aria-label="Digital Color Meter Help" onclick={()=>command('sheet',{sheet:'help'})}>?</button></footer>
 <p class="color-meter-status" role="status">{message||session.status}</p>{#if cap.windows||cap.golden}<p class="color-meter-qualification">{cap.availability}</p>{/if}
 </div>
 {#if session.sheet}<div class="color-meter-sheet" role="dialog" aria-modal="true" aria-label={session.sheet==='help'?'Digital Color Meter Help':'Meter Preferences'}><h2>{session.sheet==='help'?cap.label+' Help':'Meter Preferences'}</h2><p>{cap.colorSource}</p><p>Move the pointer over the simulated desktop. Aperture averages measured SDR channel bytes. Command-X locks X; Command-Y locks Y; Command-L locks both. Freeze retains the last real measurement. Shift-Command-C copies text; Option-Command-C copies a genuine PNG swatch to the local scene clipboard.</p><p>{cap.availability}</p>{#if session.sheet==='preferences'}<label>Value format <select data-color-meter-control="preferences:format" value={session.format} onchange={event=>command('settings',{format:event.currentTarget.value})}><option value="decimal">Decimal</option><option value="hexadecimal">Hexadecimal</option><option value="percentage">Percentage</option></select></label>{/if}<button data-color-meter-control="sheet:done" onclick={()=>command('sheet',{sheet:null})}>Done</button></div>{/if}
 {:else}<p role="alert">The original canonical meter session is unavailable.</p>{/if}
</section>
